public static int calculateInSampleSize(String mfile, int reqWidth) {
  BitmapFactory.Options bounds = new BitmapFactory.Options();
  bounds.inTempStorage = new byte[32 * 1024];
  bounds.inDither = false;
  bounds.inPurgeable = true;
  bounds.inInputShareable = true;
  bounds.inJustDecodeBounds = true;
  File file = new File(mfile);
  float rotate = getOrientation(mfile);
  FileInputStream fs = null;
  try {
    fs = new FileInputStream(file);
    if (fs != null) {
      BitmapFactory.decodeFileDescriptor(fs.getFD(), null, bounds);
    }
  } catch (FileNotFoundException e) {
    e.printStackTrace();
  } catch (IOException e) {
    e.printStackTrace();
  } catch (NullPointerException e) {
    e.printStackTrace();
  } finally {
    if (fs != null) {
      try {
        fs.close();
      } catch (IOException e) {
        e.printStackTrace();
      }
    }
  }
  final int width;
  if (rotate == 0) {
    width = bounds.outWidth;
  } else {
    width = bounds.outHeight;
  }
  Log.e("Width", String.valueOf(width));
  System.gc();
  int inSampleSize = 1;
  if (width > reqWidth) {
    inSampleSize = Math.round((float) width / (float) reqWidth);
  }
  return inSampleSize;
}
